return ['domain'=>NULL,'plural-forms'=>'nplurals=2; plural=n != 1;','language'=>'ckb','project-id-version'=>'Babilim 1.2.3','pot-creation-date'=>'2026-11-09T07:54:05+00:00','po-revision-date'=>'2026-11-09T07:54:05+00:00','x-generator'=>'Babilim','messages'=>['Sent when you press Enable Babilim, and again if the site has to register anew: your site\'s URL, the WordPress, PHP and Babilim versions, the language of your site and the languages in use on it, and a public key generated for this site.'=>'کاتێک Babilim چالاک بکە دەکەیت دەنێردرێت، هەروەها ئەگەر ماڵپەڕەکە پێویست بێت دووبارە خۆی تۆمار بکات: URLی ماڵپەڕەکەت، وەشانەکانی WordPress و PHP و Babilim، زمانی ماڵپەڕەکەت و ئەو زمانانەی لەسەری بەکاردێن، و کلیلی گشتییەک کە بۆ ئەم ماڵپەڕە دروستکراوە.','Sent on every check: the list of installed plugins and themes with the state of any Babilim translation installed for them, the languages in use, and short diagnostic codes.'=>'لە هەر پشکنینێکدا دەنێردرێت: لیستی پێوەکراو و ڕووکارە دامەزراوەکان لەگەڵ دۆخی هەر وەرگێڕانێکی Babilim کە بۆیان دامەزراوە، ئەو زمانانەی بەکاردێن، و کۆدی کورتی دەستنیشانکردن.','Every request includes your site\'s URL, and the site\'s access token is included whenever the service needs it.'=>'هەر داواکارییەک URLی ماڵپەڕەکەت لەخۆدەگرێت، و تۆکنی دەستپێگەیشتنی ماڵپەڕەکە هەر کاتێک خزمەتگوزارییەکە پێویستی پێی بێت دەنێردرێت.','What Babilim sends to the service'=>'ئەوەی Babilim بۆ خزمەتگوزارییەکە دەینێرێت','Your site\'s URL'=>'URLی ماڵپەڕەکەت','WordPress version'=>'وەشانی WordPress','PHP version'=>'وەشانی PHP','Babilim version'=>'وەشانی Babilim','Your site\'s language'=>'زمانی ماڵپەڕەکەت','Languages in use on your site'=>'ئەو زمانانەی لەسەر ماڵپەڕەکەت بەکاردێن','A public key for this site'=>'کلیلی گشتی بۆ ئەم ماڵپەڕە','A public key generated for this site, used to prove requests genuinely come from this site. Only the public half is ever sent; the private half stays on your site.'=>'کلیلی گشتییەک کە بۆ ئەم ماڵپەڕە دروستکراوە و بۆ سەلماندنی ئەوە بەکاردێت کە داواک